#include "stdlib/complex/float64/base/add.h"
#include "stdlib/complex/float64/ctor.h"
#include "stdlib/complex/float64/reim.h"

/**
* Adds two double-precision complex floating-point numbers.
*
* @param z1       input value
* @param z2       input value
* @return         result
*
* @example
* #include "stdlib/complex/float64/ctor.h"
* #include "stdlib/complex/float64/real.h"
* #include "stdlib/complex/float64/imag.h"
*
* stdlib_complex128_t z = stdlib_complex128( 3.0, -2.0 );
*
* stdlib_complex128_t out = stdlib_base_complex128_add( z, z );
*
* double re = stdlib_complex128_real( out );
* // returns 6.0
*
* double im = stdlib_complex128_imag( out );
* // returns -4.0
*/
stdlib_complex128_t stdlib_base_complex128_add( const stdlib_complex128_t z1, const stdlib_complex128_t z2 ) {
	double re1;
	double re2;
	double im1;
	double im2;
	double re;
	double im;

	stdlib_complex128_reim( z1, &re1, &im1 );
	stdlib_complex128_reim( z2, &re2, &im2 );

	re = re1 + re2;
	im = im1 + im2;

	return stdlib_complex128( re, im );
}","lineStart":1,"lineEnd":60,"totalLines":60,"truncated":false}},"title":"repos\pc-lib-3456\complex-float64-base-add\src\main.c","time":{"start":1783692921127,"end":1783692921167}},"id":"prt_f4c62039c0016i39ca7UFIUDAu","sessionID":"ses_0b39eb7e8ffe8IvUHc5sNPpRG1","messageID":"msg_f4c61ddb800134wWdBwDsfiDOD"}}

